# owner: platform
import unittest

from hourglass.models import Span
from hourglass.rounding import round_labels


class RoundLabelTests(unittest.TestCase):
    def test_label(self):
        spans = [Span(540, 1035)]
        labels = round_labels(spans, 15)
        self.assertEqual(labels, ["09:00-17:15 (8h 15m)"])

    def test_rounds_to_nearest(self):
        spans = [Span(543, 1028)]
        labels = round_labels(spans, 15)
        self.assertEqual(labels, ["09:00-17:15 (8h 15m)"])

    def test_half_step_rounds_up(self):
        spans = [Span(545, 600)]
        labels = round_labels(spans, 10)
        self.assertEqual(labels, ["09:10-10:00 (0h 50m)"])

    def test_empty(self):
        self.assertEqual(round_labels([], 15), [])

    def test_bad_steps_raise(self):
        for step in (0, -15, 7, 45, 120):
            with self.assertRaises(ValueError):
                round_labels([Span(0, 60)], step)
